INSERT INTO "teams" ("id", "slug", "name", "description", "longDescription", "icon", "departments", "roles", "skills") VALUES
('technology', 'technology', 'Technology', 'Build software, platforms, and digital experiences that power Next360.', 'Our Technology team builds the products, platforms, and digital experiences that power Next360. We work across engineering, infrastructure, and data to create reliable systems that serve customers and internal teams.', 'code', ARRAY['Technology'], ARRAY['Software Engineer', 'Frontend Developer', 'Backend Engineer', 'Cloud Engineer', 'Data Analyst'], ARRAY['React', 'TypeScript', 'Node.js', 'Python', 'AWS', 'SQL', 'Cloud']),
('product', 'product', 'Product', 'Turn customer needs into useful products and meaningful experiences.', 'The Product team shapes the direction of Next360 products. We combine user empathy with data analysis to build experiences that customers love, working closely with design, engineering, and business teams.', 'lightbulb', ARRAY['Product'], ARRAY['Product Manager', 'UX Designer'], ARRAY['Product Strategy', 'Research', 'Figma', 'Design', 'Analytics']),
('operations', 'operations', 'Operations', 'Help our products and teams run efficiently from source to customer.', 'The Operations team ensures our products reach customers reliably and our teams run efficiently. We manage supply chains, quality processes, and procurement to keep everything moving smoothly.', 'settings', ARRAY['Operations'], ARRAY['Operations Manager', 'Supply Chain Analyst', 'Quality Assurance Engineer', 'Procurement Specialist'], ARRAY['Operations', 'Supply Chain', 'Quality', 'QA', 'Testing', 'Procurement']),
('marketing', 'marketing', 'Marketing', 'Build awareness, engagement, and customer relationships.', 'The Marketing team tells the Next360 story and connects our products with the right audiences. We work across content, digital marketing, and brand to drive growth and engagement.', 'megaphone', ARRAY['Marketing'], ARRAY['Marketing Specialist', 'Content Writer'], ARRAY['Marketing', 'Content', 'SEO', 'Analytics', 'Writing']),
('sales', 'sales', 'Sales', 'Drive revenue growth by connecting customers with Next360 products.', 'The Sales team builds relationships with customers and partners, identifying opportunities to grow our customer base and deliver value through Next360 products.', 'trending-up', ARRAY['Sales'], ARRAY['Sales Executive', 'Business Development Associate'], ARRAY['Sales', 'Business Development', 'Communication', 'CRM', 'Negotiation']),
('finance', 'finance', 'Finance', 'Support responsible financial planning and operations.', 'The Finance team provides the financial insight and discipline that support Next360 growth. We manage planning, budgeting, reporting, and compliance to help the company make informed decisions.', 'calculator', ARRAY['Finance'], ARRAY['Finance Analyst'], ARRAY['Finance', 'Excel', 'Analytics', 'Reporting']),
('human-resources', 'human-resources', 'Human Resources', 'Help people and teams grow at Next360.', 'The Human Resources team builds and supports the culture at Next360. We manage recruitment, employee engagement, learning programs, and people operations to help every team member thrive.', 'users', ARRAY['Human Resources'], ARRAY['HR Generalist'], ARRAY['HR', 'Recruitment', 'Employee Relations', 'People Operations'])
